import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface PaymentResource {
  id: string;
  amount: number;
  currency: string;
  status: 'pending' | 'authorized' | 'captured' | 'released';
  holdReference: Buffer | null;
  retryCount: number;
}

class ResourcePool {
  private pool: Map<string, PaymentResource> = new Map();
  private freedSet: Set<string> = new Set();

  acquire(id: string): PaymentResource | null {
    if (this.freedSet.has(id)) {
      return null;
    }
    return this.pool.get(id) || null;
  }

  allocate(payment: PaymentResource): void {
    this.pool.set(payment.id, payment);
    this.freedSet.delete(payment.id);
  }

  release(id: string): boolean {
    const resource = this.pool.get(id);
    if (resource) {
      resource.holdReference = null;
      resource.status = 'released';
      this.pool.delete(id);
      this.freedSet.add(id);
      return true;
    }
    return false;
  }

  isFreed(id: string): boolean {
    return this.freedSet.has(id);
  }
}

class PaymentGatewayClient {
  async captureHold(ref: Buffer): Promise<{ success: boolean; code: string }> {
    await new Promise(r => setTimeout(r, Math.random() * 100));
    if (Math.random() > 0.1) return { success: true, code: 'OK' };
    return { success: false, code: 'TIMEOUT' };
  }

  async reverseCapture(ref: Buffer): Promise<void> {
    await new Promise(r => setTimeout(r, 50));
  }
}

class PaymentProcessor extends EventEmitter {
  private resourcePool = new ResourcePool();
  private gateway = new PaymentGatewayClient();
  private pendingCaptures: Map<string, Promise<void>> = new Map();
  private completionCallbacks: Map<string, (id: string) => void> = new Map();

  async initializePayment(amount: number, currency: string): Promise<string> {
    const id = crypto.randomUUID();
    const holdReference = crypto.randomBytes(32);
    const payment: PaymentResource = {
      id,
      amount,
      currency,
      status: 'pending',
      holdReference,
      retryCount: 0
    };
    this.resourcePool.allocate(payment);
    return id;
  }

  async capturePayment(paymentId: string): Promise<boolean> {
    const payment = this.resourcePool.acquire(paymentId);
    if (!payment || !payment.holdReference) return false;

    payment.status = 'authorized';
    const capturePromise = this.executeCaptureWithRetry(payment);
    this.pendingCaptures.set(paymentId, capturePromise);
    return true;
  }

  private async executeCaptureWithRetry(payment: PaymentResource): Promise<void> {
    const maxRetries = 3;

    while (payment.retryCount < maxRetries) {
      try {
        const result = await this.gateway.captureHold(payment.holdReference!);
        if (result.success) {
          payment.status = 'captured';
          this.finalizePayment(payment.id);
          return;
        }
        payment.retryCount++;
      } catch (err) {
        payment.retryCount++;
        if (payment.retryCount >= maxRetries) {
          this.handleCaptureFailure(payment.id);
          return;
        }
      }
    }
    this.handleCaptureFailure(payment.id);
  }

  private finalizePayment(paymentId: string): void {
    this.resourcePool.release(paymentId);
    this.emit('payment:completed', paymentId);
    const cb = this.completionCallbacks.get(paymentId);
    if (cb) {
      cb(paymentId);
      this.completionCallbacks.delete(paymentId);
    }
  }

  private handleCaptureFailure(paymentId: string): void {
    this.resourcePool.release(paymentId);
    this.emit('payment:failed', paymentId);
  }

  registerCompletionCallback(paymentId: string, cb: (id: string) => void): void {
    this.completionCallbacks.set(paymentId, cb);
  }

  async cancelPayment(paymentId: string): Promise<boolean> {
    const pending = this.pendingCaptures.get(paymentId);
    if (pending) {
      await pending;
    }
    // After awaiting, attempt release regardless of current state
    // This handles the case where capture completed but we still want cleanup
    const released = this.resourcePool.release(paymentId);
    if (released) {
      this.emit('payment:cancelled', paymentId);
    }
    this.pendingCaptures.delete(paymentId);
    return released;
  }
}

// Kubernetes health check and orchestration layer
class PaymentServiceController {
  private processor = new PaymentProcessor();
  private activePayments: Set<string> = new Set();

  async processOrder(amount: number, currency: string): Promise<string> {
    const paymentId = await this.processor.initializePayment(amount, currency);
    this.activePayments.add(paymentId);

    this.processor.registerCompletionCallback(paymentId, (id) => {
      this.activePayments.delete(id);
    });

    await this.processor.capturePayment(paymentId);
    return paymentId;
  }

  async handlePodTermination(): Promise<void> {
    const cancellations = Array.from(this.activePayments).map(id =>
      this.processor.cancelPayment(id)
    );
    await Promise.all(cancellations);
    this.activePayments.clear();
  }

  getActiveCount(): number {
    return this.activePayments.size;
  }
}

export { PaymentProcessor, PaymentServiceController, ResourcePool };
